from itertools import combinations

nodes = ["A", "B", "C", "D", "E"]
edges = {frozenset(e) for e in [("A","B"),("B","C"),("C","D"),("D","E"),("E","A"),("A","C")]}

omega = 0
for r in range(1, len(nodes) + 1):
    for S in combinations(nodes, r):
        if all(frozenset((u, v)) in edges for u, v in combinations(S, 2)):
            omega = max(omega, r)

col = {"A": 1, "B": 2, "C": 3, "D": 1, "E": 2}
assert all(col[u] != col[v] for u, v in [tuple(e) for e in edges])
chi = max(omega, max(col.values()))
print(chi)
